package com.hibernate.ecommerce.model;import jakarta.persistence.*;import jakarta.validation.constraints.Positive;import lombok.*;@Entity@Getter@Setter@AllArgsConstructor@NoArgsConstructor@Builderpublic class Orderdetails {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @ManyToOne    private Order order;    @ManyToOne    private Product product;    @Positive    private Double price;    @Positive    private int quantity;}